{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "~((df['proto'] != 'tcp') & ~((df['swin'] == 0) & (df['dwin'] == 0) & (df['stcpb'] == 0) & (df['dtcpb'] == 0) & (df['tcprtt'] == 0) & (df['synack'] == 0) & (df['ackdat'] == 0)))"
      ],
      "features": ["proto", "swin", "dwin", "stcpb", "dtcpb", "tcprtt", "synack", "ackdat"],
      "rationale": "TCP-specific fields must be zero for non-TCP protocols."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "~((df['service'] == 'ftp') & (df['proto'] == 'tcp') & ~((df['is_ftp_login'] == 0) & (df['ct_ftp_cmd'] == 0)))"
      ],
      "features": ["proto", "service", "is_ftp_login", "ct_ftp_cmd"],
      "rationale": "FTP-specific fields must be zero when service is not FTP or protocol is not TCP."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "~((df['service'] == 'http') & (df['proto'] == 'tcp') & ~((df['ct_flw_http_mthd'] == 0) & (df['trans_depth'] == 0) & (df['response_body_len'] == 0)))"
      ],
      "features": ["proto", "service", "ct_flw_http_mthd", "trans_depth", "response_body_len"],
      "rationale": "HTTP-specific fields must be zero when service is not HTTP or protocol is not TCP."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "~((df['proto'] == 'icmp') & ~((df['sport'] == 0) & (df['dsport'] == 0)))"
      ],
      "features": ["proto", "sport", "dsport"],
      "rationale": "ICMP does not use ports, so source and destination ports must be zero."
    }
  ]
}
